<script setup lang="ts">
import {ref,computed,useId,onMounted,onUnmounted,nextTick,watch} from 'vue';import {ChevronDown,Check,Search} from './icons';
const props=withDefaults(defineProps<{modelValue:string,options:{value:string,label:string,hint?:string}[],label:string,placeholder?:string,disabled?:boolean,searchable?:boolean}>(),{placeholder:'Choose an option',disabled:false,searchable:false});
const emit=defineEmits<{(event:'update:modelValue',value:string):void}>();const id=useId();const opened=ref(false),index=ref(0),search=ref(''),root=ref<HTMLElement|null>(null),trigger=ref<HTMLButtonElement|null>(null);
const choices=computed(()=>props.options.filter(o=>o.label.toLowerCase().includes(search.value.toLowerCase())));const selected=computed(()=>props.options.find(o=>o.value===props.modelValue));
function open(){if(props.disabled)return;opened.value=!opened.value;search.value='';index.value=Math.max(0,props.options.findIndex(o=>o.value===props.modelValue));void nextTick(()=>scroll())}
function select(value:string){emit('update:modelValue',value);opened.value=false;trigger.value?.focus()}
function scroll(){document.getElementById(`${id}-${index.value}`)?.scrollIntoView({block:'nearest'})}
async function key(e:KeyboardEvent){if(['ArrowDown','ArrowUp','Home','End','Enter',' ','Escape'].includes(e.key)){if(e.key==='Escape'){if(opened.value)e.stopPropagation();opened.value=false;return};e.preventDefault();if(!opened.value){open();return};if(e.key==='Enter'||e.key===' '){const c=choices.value[index.value];if(c)select(c.value);return};if(e.key==='Home')index.value=0;else if(e.key==='End')index.value=choices.value.length-1;else index.value=(index.value+(e.key==='ArrowDown'?1:-1)+choices.value.length)%Math.max(1,choices.value.length);await nextTick();scroll()}else if(e.key==='Tab')opened.value=false;}
function outside(e:PointerEvent){if(!root.value?.contains(e.target as Node))opened.value=false}
watch(search,()=>index.value=0);onMounted(()=>document.addEventListener('pointerdown',outside));onUnmounted(()=>document.removeEventListener('pointerdown',outside));
</script>
<template><div class="solara-select" ref="root" :class="{opened}"><button ref="trigger" type="button" role="combobox" :aria-label="label" :aria-expanded="opened" aria-haspopup="listbox" :aria-controls="id" :aria-activedescendant="opened?`${id}-${index}`:undefined" :disabled="disabled" @click="open" @keydown="key"><span :class="{placeholder:!selected}">{{selected?.label||placeholder}}</span><ChevronDown/></button><Transition name="select"><div v-if="opened" class="select-popover"><div v-if="searchable" class="select-search"><Search/><input v-model="search" :aria-label="`Filter ${label}`" placeholder="Type to filter…" @keydown.esc="opened=false"></div><div :id="id" role="listbox" :aria-label="label" class="select-options"><button v-for="(o,i) in choices" :id="`${id}-${i}`" :key="o.value" type="button" role="option" :aria-selected="o.value===modelValue" :class="{highlighted:i===index}" @pointermove="index=i" @click="select(o.value)" tabindex="-1"><span><strong>{{o.label}}</strong><small v-if="o.hint">{{o.hint}}</small></span><Check v-if="o.value===modelValue"/></button><p v-if="!choices.length">No matching options.</p></div></div></Transition></div></template>
